package org.daidai.modules.music;

import android.content.*;
import android.net.Uri;
import android.provider.OpenableColumns;
import android.provider.DocumentsContract;
import android.database.Cursor;
import android.media.MediaMetadataRetriever;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.security.MessageDigest;
import java.math.BigDecimal;
import java.math.RoundingMode;

/** A persistent catalogue and an independent URI playback queue. Removing queue entries keeps metadata. */
public final class MusicLibrary {
    private static final String PREFS="music_module";
    public static final class Track {
        /** artist remains an alias for old integrations; new editors use vocalist. */
        public final String uri,title,artist,vocalist,composer,arranger,notes,tags,lrcPath,coverPath,bpmText;
        /** bpmText preserves decimal precision. bpm is a rounded compatibility view; rating -1 is unset. */
        public final int bpm,rating; public final boolean instrumental; public final long duration;
        public Track(String uri,String title){this(uri,title,"","","","","","",0,-1,false,0,"");}
        public Track(String uri,String title,String vocalist,String composer,String arranger,String notes,String tags,String lrcPath,int bpm,int rating,boolean instrumental,long duration,String coverPath){
            this(uri,title,vocalist,composer,arranger,notes,tags,lrcPath,bpm>0?Integer.toString(bpm):"",rating,instrumental,duration,coverPath);
        }
        public Track(String uri,String title,String vocalist,String composer,String arranger,String notes,String tags,String lrcPath,String bpm,int rating,boolean instrumental,long duration,String coverPath){
            this.uri=clean(uri);this.title=clean(title);this.artist=clean(vocalist);this.vocalist=clean(vocalist);this.composer=clean(composer);this.arranger=clean(arranger);this.notes=clean(notes);this.tags=clean(tags);this.lrcPath=clean(lrcPath);this.bpmText=safeBpm(bpm);this.bpm=this.bpmText.isEmpty()?0:new BigDecimal(this.bpmText).setScale(0,RoundingMode.HALF_UP).min(BigDecimal.valueOf(Integer.MAX_VALUE)).intValue();this.rating=rating<0?-1:Math.min(10,rating);this.instrumental=instrumental;this.duration=Math.max(0,duration);this.coverPath=clean(coverPath);
        }
        public Track withMeta(String title,String vocalist,String composer,String arranger,String notes,String tags,int bpm,int rating,boolean instrumental,String lrcPath,String coverPath){return new Track(uri,title,vocalist,composer,arranger,notes,tags,lrcPath,bpm,rating,instrumental,duration,coverPath);}
        public Track withMeta(String title,String vocalist,String composer,String arranger,String notes,String tags,String bpm,int rating,boolean instrumental,String lrcPath,String coverPath){return new Track(uri,title,vocalist,composer,arranger,notes,tags,lrcPath,bpm,rating,instrumental,duration,coverPath);}
        private static String clean(String s){return s==null?"":s;}
    }
    /** Empty is unset; positive decimal input has no fixed decimal-place limit. */
    public static String normalizeBpm(String raw){String value=raw==null?"":raw.trim();if(value.isEmpty())return "";if(!value.matches("(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)"))throw new IllegalArgumentException("BPM must be a positive decimal");BigDecimal bpm=new BigDecimal(value);if(bpm.signum()<=0)throw new IllegalArgumentException("BPM must be positive");return bpm.stripTrailingZeros().toPlainString();}
    private static String safeBpm(String raw){try{return normalizeBpm(raw);}catch(Exception ignored){return "";}}
    public static String measuredBpm(String raw,boolean keepDecimal){String normalized=normalizeBpm(raw);if(normalized.isEmpty())return "";return new BigDecimal(normalized).setScale(keepDecimal?1:0,RoundingMode.HALF_UP).toPlainString();}
    private static Track decode(JSONObject t){String vocalist=t.has("vocalist")?t.optString("vocalist"):t.optString("artist");int rating=t.optInt("rating",-1);if(!t.optBoolean("ratingSet",false)&&rating==0)rating=-1;return new Track(t.optString("uri"),t.optString("title"),vocalist,t.optString("composer"),t.optString("arranger"),t.optString("notes"),t.optString("tags"),t.optString("lrcPath"),t.optString("bpm"),rating,t.optBoolean("instrumental"),t.optLong("duration"),t.optString("coverPath"));}
    private static JSONObject encode(Track t)throws JSONException{return new JSONObject().put("uri",t.uri).put("title",t.title).put("vocalist",t.vocalist).put("composer",t.composer).put("arranger",t.arranger).put("notes",t.notes).put("tags",t.tags).put("lrcPath",t.lrcPath).put("bpm",t.bpmText).put("rating",t.rating).put("ratingSet",t.rating>=0).put("instrumental",t.instrumental).put("duration",t.duration).put("coverPath",t.coverPath);}
    private static String identity(String raw){try{Uri uri=Uri.parse(raw);String id=DocumentsContract.getDocumentId(uri);return "document:"+uri.getAuthority()+":"+id;}catch(Exception ignored){return raw;}}
    private static Track existing(Map<String,Track> rows,String uri){Track direct=rows.get(uri);if(direct!=null)return direct;String id=identity(uri);for(Track t:rows.values())if(identity(t.uri).equals(id))return t;return null;}
    private static Track atUri(Track t,String uri){return new Track(uri,t.title,t.vocalist,t.composer,t.arranger,t.notes,t.tags,t.lrcPath,t.bpmText,t.rating,t.instrumental,t.duration,t.coverPath);}
    private static LinkedHashMap<String,Track> readCatalogue(Context c){LinkedHashMap<String,Track> rows=new LinkedHashMap<>();SharedPreferences prefs=c.getSharedPreferences(PREFS,0);try{JSONArray a=new JSONArray(prefs.getString("catalogue","[]"));for(int i=0;i<a.length();i++){JSONObject v=a.optJSONObject(i);if(v!=null){Track t=decode(v);if(!t.uri.isEmpty()&&existing(rows,t.uri)==null)rows.put(t.uri,t);}}}catch(Exception ignored){}try{JSONArray a=new JSONArray(prefs.getString("queue","[]"));for(int i=0;i<a.length();i++){JSONObject v=a.optJSONObject(i);if(v!=null){Track t=decode(v);if(!t.uri.isEmpty()&&existing(rows,t.uri)==null)rows.put(t.uri,t);}}}catch(Exception ignored){}return rows;}
    private static void writeCatalogue(Context c,Map<String,Track> rows){JSONArray a=new JSONArray();for(Track t:rows.values())try{a.put(encode(t));}catch(Exception ignored){}c.getSharedPreferences(PREFS,0).edit().putString("catalogue",a.toString()).apply();}
    public static synchronized ArrayList<Track> catalogue(Context c){return new ArrayList<>(readCatalogue(c).values());}
    public static synchronized Track find(Context c,String uri){return existing(readCatalogue(c),uri);}
    public static synchronized void upsert(Context c,Collection<Track> tracks){LinkedHashMap<String,Track> rows=readCatalogue(c);for(Track t:tracks)if(t!=null&&!t.uri.isEmpty()){Track old=existing(rows,t.uri);String uri=old==null?t.uri:old.uri;rows.put(uri,atUri(t,uri));}writeCatalogue(c,rows);}
    /** New scans fill previously unavailable file tags without replacing saved or manually cleared fields. */
    public static synchronized void discover(Context c,Collection<Track> tracks){LinkedHashMap<String,Track> rows=readCatalogue(c);for(Track t:tracks)if(t!=null&&!t.uri.isEmpty()){Track old=existing(rows,t.uri);if(old==null)rows.put(t.uri,t);else if(!manuallyEdited(c,old.uri)){Track merged=old.withMeta(old.title,first(old.vocalist,t.vocalist),first(old.composer,t.composer),first(old.arranger,t.arranger),old.notes,old.tags,old.bpmText.isEmpty()?t.bpmText:old.bpmText,old.rating,old.instrumental,old.lrcPath,first(old.coverPath,t.coverPath));rows.put(old.uri,merged);}}writeCatalogue(c,rows);}
    public static synchronized void markMetadataEdited(Context c,String uri){Set<String> before=c.getSharedPreferences(PREFS,0).getStringSet("metadata_manually_edited",Collections.emptySet());HashSet<String> edited=new HashSet<>(before);edited.add(identity(uri));c.getSharedPreferences(PREFS,0).edit().putStringSet("metadata_manually_edited",edited).apply();}
    private static boolean manuallyEdited(Context c,String uri){return c.getSharedPreferences(PREFS,0).getStringSet("metadata_manually_edited",Collections.emptySet()).contains(identity(uri));}
    public static boolean needsMetadataRefresh(Context c,Track t){return !manuallyEdited(c,t.uri)&&(t.bpmText.isEmpty()||t.coverPath.isEmpty()||t.vocalist.isEmpty());}
    public static synchronized ArrayList<Track> load(Context c){LinkedHashMap<String,Track> catalogue=readCatalogue(c);ArrayList<Track> rows=new ArrayList<>();HashSet<String> seen=new HashSet<>();try{JSONArray a=new JSONArray(c.getSharedPreferences(PREFS,0).getString("queue","[]"));for(int i=0;i<a.length();i++){Object raw=a.opt(i);String uri=raw instanceof JSONObject?((JSONObject)raw).optString("uri"):raw instanceof String?(String)raw:"";Track t=existing(catalogue,uri);if(t!=null&&seen.add(identity(uri)))rows.add(t);}}catch(Exception ignored){}return rows;}
    /** Legacy save API updates supplied metadata and only replaces the queue, never the catalogue. */
    public static synchronized void save(Context c,List<Track> tracks){upsert(c,tracks);LinkedHashMap<String,Track> catalogue=readCatalogue(c);JSONArray a=new JSONArray();HashSet<String> seen=new HashSet<>();for(Track t:tracks)if(t!=null&&seen.add(identity(t.uri))){Track saved=existing(catalogue,t.uri);a.put(saved==null?t.uri:saved.uri);}c.getSharedPreferences(PREFS,0).edit().putString("queue",a.toString()).apply();}
    public static synchronized void addToQueue(Context c,Collection<Track> tracks){ArrayList<Track> queue=load(c);HashSet<String> uris=new HashSet<>();for(Track t:queue)uris.add(identity(t.uri));for(Track t:tracks)if(uris.add(identity(t.uri)))queue.add(t);save(c,queue);}
    public static synchronized void update(Context c,Track t){upsert(c,Collections.singleton(t));}
    public static synchronized boolean updateBpm(Context c,String uri,String value){String bpm=normalizeBpm(value);Track t=find(c,uri);if(t==null)return false;update(c,t.withMeta(t.title,t.vocalist,t.composer,t.arranger,t.notes,t.tags,bpm,t.rating,t.instrumental,t.lrcPath,t.coverPath));markMetadataEdited(c,uri);return true;}
    public static synchronized void removeFromQueue(Context c,String uri){ArrayList<Track> queue=load(c);String id=identity(uri);queue.removeIf(t->identity(t.uri).equals(id));save(c,queue);}
    public static synchronized void removeFromQueue(Context c,Collection<String> uris){HashSet<String> ids=new HashSet<>();for(String uri:uris)ids.add(identity(uri));ArrayList<Track> queue=load(c);queue.removeIf(t->ids.contains(identity(t.uri)));save(c,queue);}
    /** Called only after the provider confirmed file deletion; does not itself delete audio. */
    public static synchronized void removeEverywhere(Context c,String uri){
        String id=identity(uri);LinkedHashMap<String,Track> catalogue=readCatalogue(c);ArrayList<Track> queue=load(c);catalogue.entrySet().removeIf(e->identity(e.getKey()).equals(id));queue.removeIf(t->identity(t.uri).equals(id));JSONArray entries=new JSONArray(),queued=new JSONArray();for(Track t:catalogue.values())try{entries.put(encode(t));}catch(JSONException ignored){}for(Track t:queue)queued.put(t.uri);
        HashSet<String> edited=new HashSet<>(c.getSharedPreferences(PREFS,0).getStringSet("metadata_manually_edited",Collections.emptySet()));edited.remove(id);c.getSharedPreferences(PREFS,0).edit().putString("catalogue",entries.toString()).putString("queue",queued.toString()).putStringSet("metadata_manually_edited",edited).apply();MusicCollections.prune(c,catalogue.keySet());
    }
    public static String title(Context c,Uri uri){try(Cursor cursor=c.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())return cursor.getString(0);}catch(Exception ignored){}return org.daidai.modules.shared.Texts.get(c,"music_audio");}
    public static Track readMetadata(Context c,Uri uri){String name=title(c,uri),vocalist="",composer="",arranger="",cover="";long length=0;AudioFileTags.Tags tags=new AudioFileTags.Tags();try(InputStream in=c.getContentResolver().openInputStream(uri)){if(in!=null)tags=AudioFileTags.read(in);}catch(Exception ignored){}if(!tags.title.isEmpty())name=tags.title;vocalist=first(tags.artist,tags.albumArtist);composer=tags.composer;arranger=tags.arranger;byte[] art=tags.picture;
        MediaMetadataRetriever r=new MediaMetadataRetriever();try{r.setDataSource(c,uri);String v=r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_TITLE);if(tags.title.isEmpty()&&v!=null&&!v.trim().isEmpty())name=v;vocalist=first(vocalist,first(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_ARTIST),r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_ALBUMARTIST)));composer=first(composer,first(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_COMPOSER),r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_WRITER)));String d=r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION);if(d!=null)length=Long.parseLong(d);if(art==null)art=r.getEmbeddedPicture();}catch(Exception ignored){}finally{try{r.release();}catch(Exception ignored){}}
        if(art!=null)cover=saveEmbeddedCover(c,art);return new Track(uri.toString(),name,vocalist,composer,arranger,"","","",tags.bpm,-1,false,length,cover);}
    private static String saveEmbeddedCover(Context c,byte[] raw){if(raw.length==0||raw.length>8*1024*1024)return "";Bitmap image=null;File temp=null;try{MessageDigest md=MessageDigest.getInstance("SHA-256");StringBuilder id=new StringBuilder();for(byte b:md.digest(raw))id.append(String.format(Locale.ROOT,"%02x",b&255));File dir=new File(c.getFilesDir(),"covers");if(!dir.exists()&&!dir.mkdirs())return "";File output=new File(dir,"embedded-"+id+".png");if(output.isFile()&&output.length()>0)return output.getAbsolutePath();BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(raw,0,raw.length,options);if(options.outWidth<1||options.outHeight<1||options.outWidth>50000||options.outHeight>50000||(long)options.outWidth*options.outHeight>200000000L)return "";options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>1024)options.inSampleSize*=2;options.inJustDecodeBounds=false;image=BitmapFactory.decodeByteArray(raw,0,raw.length,options);if(image==null)return "";temp=File.createTempFile("embedded-",".tmp",dir);try(OutputStream out=new FileOutputStream(temp)){if(!image.compress(Bitmap.CompressFormat.PNG,100,out))return "";}if(!temp.renameTo(output))return "";temp=null;return output.getAbsolutePath();}catch(Exception ignored){return "";}finally{if(temp!=null)temp.delete();if(image!=null)image.recycle();}}
    private static String first(String a,String b){return a!=null&&!a.trim().isEmpty()?a:b==null?"":b;}
    private static final Map<String,NavigableMap<Long,String>> LYRIC_CACHE=Collections.synchronizedMap(new LinkedHashMap<String,NavigableMap<Long,String>>(16,.75f,true){protected boolean removeEldestEntry(Map.Entry<String,NavigableMap<Long,String>> e){return size()>12;}});
    private static final Set<String> LYRIC_LOADING=Collections.synchronizedSet(new HashSet<>());
    private static final ExecutorService LYRIC_WORKER=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"music-lyrics");t.setDaemon(true);return t;});
    public static String lyricAt(Context c,Track t,long ms){return t.instrumental?org.daidai.modules.shared.Texts.get(c,"library_instrumental_lyrics"):lyricAt(t,ms);}
    /** Compatibility overload; localized instrumental labels require the Context overload. */
    public static String lyricAt(Track t,long ms){if(t.instrumental||t.lrcPath.isEmpty())return "";File file=new File(t.lrcPath);String key=t.lrcPath+":"+file.lastModified()+":"+file.length();NavigableMap<Long,String> lines=LYRIC_CACHE.get(key);if(lines==null){if(LYRIC_LOADING.add(key))LYRIC_WORKER.execute(()->{TreeMap<Long,String> parsed=new TreeMap<>();try(BufferedReader reader=new BufferedReader(new InputStreamReader(new FileInputStream(file),"UTF-8"))){String line;java.util.regex.Pattern pattern=java.util.regex.Pattern.compile("\\[(\\d+):(\\d{2})(?:\\.(\\d{1,3}))?\\]");while((line=reader.readLine())!=null){java.util.regex.Matcher matcher=pattern.matcher(line);ArrayList<Long> times=new ArrayList<>();int end=0;while(matcher.find()){long at=(Long.parseLong(matcher.group(1))*60+Long.parseLong(matcher.group(2)))*1000L;String fraction=matcher.group(3);if(fraction!=null)at+=Integer.parseInt(fraction)*(fraction.length()==1?100:fraction.length()==2?10:1);times.add(at);end=matcher.end();}String content=line.substring(end).trim();for(long time:times)parsed.put(time,content);}}catch(Exception ignored){}finally{LYRIC_CACHE.put(key,parsed);LYRIC_LOADING.remove(key);}});return "";}Map.Entry<Long,String> entry=lines.floorEntry(ms);return entry==null?"":entry.getValue();}
}
